/* Ghibli — watercolor meadows, warm paper skies, gentle wonder */
.theme-ghibli {
  --bg: oklch(0.952 0.018 92.7);
  --surface: oklch(0.975 0.015 94.2);
  --surface-2: oklch(0.913 0.026 90.1);
  --fg: oklch(0.384 0.020 73.3);
  --fg-muted: oklch(0.601 0.030 80.1);
  --accent: oklch(0.650 0.090 146.3);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.756 0.076 231.6);
  --line: oklch(0.869 0.032 86.5);
  --success: oklch(0.650 0.090 146.3);
  --warning: oklch(0.789 0.125 87.6);
  --danger: oklch(0.637 0.122 38.6);
  --radius: 1rem;
  --radius-sm: 0.75rem;
  --radius-lg: 1.25rem;
  --radius-pill: 9999px;
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Mali", cursive;
  --font-body: "Mali", cursive;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-ghibli h1,
.theme-ghibli h2,
.theme-ghibli h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-ghibli { background-image: radial-gradient(ellipse 120px 50px at 15% 8%, oklch(1 0 0 / 70%), transparent), radial-gradient(ellipse 160px 60px at 75% 15%, oklch(1 0 0 / 60%), transparent), linear-gradient(180deg, oklch(0.92 0.03 220 / 40%), transparent 260px); }
.theme-ghibli h1 { color: #4a4238; font-weight: 600; }
.theme-ghibli h2::before { content: "❀ "; color: var(--accent-2); }
.theme-ghibli button { font-weight: 600; }

/* alt-mode — night forest: Totoro dusk, firefly dots, lantern amber */
.theme-ghibli.alt-mode {
  --bg: oklch(0.245 0.035 210.0);
  --surface: oklch(0.290 0.038 205.0);
  --surface-2: oklch(0.340 0.042 200.0);
  --fg: oklch(0.930 0.025 92.0);
  --fg-muted: oklch(0.680 0.035 180.0);
  --accent: oklch(0.780 0.115 90.0);
  --accent-fg: oklch(0.240 0.035 210.0);
  --accent-2: oklch(0.720 0.090 146.3);
  --line: oklch(0.55 0.05 195 / 40%);
  --success: oklch(0.720 0.090 146.3);
  --warning: oklch(0.800 0.120 88.0);
  --danger: oklch(0.680 0.130 38.6);
  --shadow-1: 0 2px 6px oklch(0 0 0 / 35%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 45%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 55%);
  --glow: 0 0 12px color-mix(in oklab, var(--accent) 40%, transparent);
  background-image:
    radial-gradient(circle 2px at 18% 22%, oklch(0.85 0.14 110 / 60%) 0 2px, transparent 2px),
    radial-gradient(circle 2px at 68% 12%, oklch(0.85 0.14 110 / 50%) 0 2px, transparent 2px),
    radial-gradient(circle 2px at 88% 42%, oklch(0.85 0.14 110 / 45%) 0 2px, transparent 2px),
    radial-gradient(circle 2px at 40% 62%, oklch(0.85 0.14 110 / 35%) 0 2px, transparent 2px),
    linear-gradient(180deg, oklch(0.20 0.04 230 / 60%), transparent 260px);
}
.theme-ghibli.alt-mode h1 { color: var(--fg); }
.theme-ghibli.alt-mode h2::before { color: var(--accent); }


/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
